/** In-memory control and delivery topics for SDK integration tests. */
export class DeliveryTestGateway {
    controlPushes = [];
    packets = [];
    invitationHandler;
    currentDelivery;
    leaves = 0;
    push(event, payload) {
        this.controlPushes.push({ event, payload });
        if (event === "claim") {
            const deliveryId = payload.deliveryId;
            return Promise.resolve({
                result: "claimed",
                deliveryId,
                ownerGeneration: 1,
                joinToken: `chj_token_${deliveryId.slice(4)}`,
                joinTokenExpiresAt: "2099-07-29T16:01:00.000Z",
                deliveryExpiresAt: "2099-07-29T17:00:00.000Z",
            });
        }
        if (event === "join_token") {
            const deliveryId = payload.deliveryId;
            return Promise.resolve({
                deliveryId,
                ownerGeneration: 2,
                joinToken: `chj_reconnect_${deliveryId.slice(4)}`,
                joinTokenExpiresAt: "2099-07-29T16:01:00.000Z",
                deliveryExpiresAt: "2099-07-29T17:00:00.000Z",
            });
        }
        return Promise.resolve({});
    }
    on(event, handler) {
        if (event === "delivery_invitation")
            this.invitationHandler = handler;
    }
    async join(_topic, _payload) {
        const delivery = this.currentDelivery;
        if (!delivery)
            throw new Error("No prepared delivery is queued");
        return {
            joinReply: delivery,
            push: async (_event, payload) => {
                const packet = payload;
                this.packets.push(packet);
                return {
                    deliveryId: packet.deliveryId,
                    seq: packet.seq,
                    packetId: packet.packetId,
                    phase: "applied",
                    result: packet.payload.kind === "channel.delivery.terminal"
                        ? {}
                        : { providerReference: `pref_v1_${packet.packetId}` },
                };
            },
            on: () => undefined,
            onClose: () => undefined,
            leave: () => {
                this.leaves += 1;
            },
        };
    }
    /** Publish one prepared delivery and wait for its delivery topic to close. */
    async deliver(delivery) {
        const expectedLeaves = this.leaves + 1;
        this.currentDelivery = delivery;
        this.invitationHandler?.({
            protocol: "channel_delivery_v1",
            deliveryId: delivery.deliveryId,
            canonicalThreadId: delivery.canonicalThreadId,
            channelName: delivery.channelName,
            adapter: delivery.adapter,
        });
        const deadline = Date.now() + 1_000;
        while (this.leaves !== expectedLeaves) {
            if (Date.now() >= deadline) {
                throw new Error("Timed out waiting for delivery topic to close");
            }
            await new Promise((resolve) => setTimeout(resolve, 1));
        }
    }
}
/** Build one valid prepared delivery for SDK integration tests. */
export function preparedDelivery(suffix, adapter, input) {
    // Packet contract requires `dlv_` + 8..128 charset chars.
    const idSuffix = suffix.length >= 8 ? suffix : `${suffix}_pad000`.slice(0, 12);
    const normalizedInput = input.kind === "text"
        ? {
            ...input,
            text: input.text ?? "",
            messageRef: input.messageRef ?? {
                id: `pref_v1_message_${idSuffix}`,
            },
            operation: "operation" in input && input.operation
                ? input.operation
                : {
                    kind: "created",
                    logicalMessageId: "pid_v1_abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQ",
                    revisionId: "pid_v1_ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopq",
                    mentioned: false,
                },
        }
        : input;
    return {
        protocol: "channel_delivery_v1",
        deliveryId: `dlv_${idSuffix}`,
        deliveryExpiresAt: "2099-07-29T17:00:00.000Z",
        canonicalThreadId: `thread_${idSuffix}`,
        appUserId: `app_user_${idSuffix}`,
        channelId: "channel_support",
        channelName: "support",
        adapter,
        tenant: { id: `tenant_${idSuffix}` },
        installation: { id: `installation_${idSuffix}` },
        conversation: { id: `conversation_${idSuffix}`, kind: "thread" },
        turn: {
            eventId: `evt_${idSuffix}`,
            receivedAt: "2026-07-29T17:00:00.000Z",
            input: normalizedInput,
            actor: {
                externalUserId: `user_${idSuffix}`,
                kind: "human",
                displayName: "Ada",
            },
            raw: { deliveryKind: input.kind },
        },
    };
}
